using System.Collections.Immutable;
using System.Globalization;
using Microsoft.Accordant;

namespace Orleans.Durable.Storage.Testing;

/// <summary>
/// The abstract state of a process's journals, as <c>JournalStore</c>'s answers reveal it (journals.md §2): each
/// journal's <see cref="JournalModelState"/>, the state of <see cref="JournalModel"/> (verification.md §3.1, §3.4), and
/// what the environment's steps decide of the answers: whether the process serves the journals' open ledger.
/// </summary>
/// <remarks>
/// Written by hand rather than generated by Accordant's <c>[State]</c>, which takes only primitives, collections, and
/// <c>[State]</c> classes: each journal's state is the model's own immutable <see cref="JournalModelState"/>, which the
/// linearizability checker shares. A frozen state refuses changes, and a clone is unfrozen.
/// </remarks>
internal sealed class JournalStoreState : IState
{
    private ImmutableArray<JournalModelState> _journals = [.. JournalStoreSpec.Keys.Select(static _ => JournalModelState.Absent)];
    private bool _served = true;

    /// <summary>Gets each journal's state, by its index in <see cref="JournalStoreSpec.Keys"/>.</summary>
    public ImmutableArray<JournalModelState> Journals => _journals;

    /// <summary>Gets or sets a value indicating whether the process serves the journals' open ledger's writer.</summary>
    public bool Served
    {
        get => _served;
        set
        {
            ThrowIfFrozen();
            _served = value;
        }
    }

    /// <inheritdoc/>
    public bool IsFrozen { get; private set; }

    /// <summary>Sets the state of the journal <paramref name="key"/>.</summary>
    public void SetJournal(int key, JournalModelState journal)
    {
        ThrowIfFrozen();
        _journals = _journals.SetItem(key, journal);
    }

    /// <inheritdoc/>
    public void Freeze() => IsFrozen = true;

    /// <inheritdoc/>
    public IState Clone() => new JournalStoreState { _journals = _journals, _served = _served };

    /// <summary>Returns the FNV-1a hash of <see cref="StringRepresentation"/>, which names every fact of the state.</summary>
    public ulong GetStateHash()
    {
        var hash = 14695981039346656037UL;
        foreach (var character in StringRepresentation())
        {
            hash = unchecked((hash ^ character) * 1099511628211UL);
        }

        return hash;
    }

    /// <summary>
    /// Returns every fact of the state: each journal's names, content, its generation's appends and base, whether it is
    /// expired, and the versions it held; and whether the process serves the journals.
    /// </summary>
    public string StringRepresentation()
    {
        var text = new System.Text.StringBuilder();
        for (var key = 0; key < _journals.Length; key++)
        {
            var journal = _journals[key];
            _ = text.Append(CultureInfo.InvariantCulture, $"{JournalStoreSpec.Keys[key]}: {journal}{(journal.Expired ? " expired" : string.Empty)}, ")
                .Append(CultureInfo.InvariantCulture, $"{journal.Appends} appends on {journal.BaseLength} bytes, held ")
                .AppendJoin('|', journal.Held.Order(StringComparer.Ordinal))
                .Append("; ");
        }

        return text.Append(_served ? "served" : "unserved").ToString();
    }

    public override string ToString() => StringRepresentation();

    private void ThrowIfFrozen()
    {
        if (IsFrozen)
        {
            throw new InvalidOperationException("A frozen state does not change.");
        }
    }
}

/// <summary>The kind of a <see cref="JournalWrite"/>: the writes a caller encodes (journals.md §2.2).</summary>
internal enum JournalWriteKind
{
    /// <summary>An <c>Append</c>.</summary>
    Append,

    /// <summary>A <c>Replace</c>.</summary>
    Replace,

    /// <summary>A <c>Delete</c>.</summary>
    Delete,
}

/// <summary>What the environment does while a <see cref="JournalWrite"/> is in flight.</summary>
internal enum JournalDisruption
{
    /// <summary>Nothing: the write meets a steady process.</summary>
    None,

    /// <summary>A takeover replaces the journals' open ledger while the write's load is in flight, which fences it.</summary>
    Takeover,

    /// <summary>The process crashes once the write's batch reaches its replica, which leaves its outcome unknown.</summary>
    Crash,
}

/// <summary>
/// A write of the journal <see cref="JournalStoreSpec.Keys"/>[<paramref name="Key"/>], at the version the caller learned
/// <paramref name="Back"/> answers before its newest of the journal (0 is the newest; <c>Origin</c> is its first), with
/// <see cref="JournalStoreSpec.Payload"/> of <paramref name="Value"/>, during <paramref name="Disruption"/>.
/// </summary>
internal sealed record JournalWrite(int Key, JournalWriteKind Kind, int Back, byte Value, JournalDisruption Disruption = JournalDisruption.None)
{
    /// <summary>Gets the operation of <see cref="JournalModel"/> the write is.</summary>
    public JournalOperationKind Operation => Kind switch
    {
        JournalWriteKind.Append => JournalOperationKind.Append,
        JournalWriteKind.Replace => JournalOperationKind.Replace,
        JournalWriteKind.Delete => JournalOperationKind.Delete,
        _ => throw new ArgumentOutOfRangeException(nameof(Kind), Kind, "Undefined write kind."),
    };

    /// <summary>Gets the write's payload: an append's, or a replace's snapshot, empty for a delete.</summary>
    public byte[] Payload => JournalStoreSpec.Payload(Kind, Value);

    public override string ToString()
    {
        var disruption = Disruption switch
        {
            JournalDisruption.None => string.Empty,
            JournalDisruption.Takeover => " during a takeover",
            JournalDisruption.Crash => " during a crash",
            _ => throw new ArgumentOutOfRangeException(nameof(Disruption), Disruption, "Undefined disruption."),
        };
        return string.Create(
            CultureInfo.InvariantCulture,
            $"{Kind}({JournalStoreSpec.Keys[Key]}, back {Back}, {JournalModel.Describe(Payload)}){disruption}");
    }
}

/// <summary>A read of the journal <see cref="JournalStoreSpec.Keys"/>[<paramref name="Key"/>].</summary>
internal sealed record JournalRead(int Key)
{
    public override string ToString() => string.Create(CultureInfo.InvariantCulture, $"Read({JournalStoreSpec.Keys[Key]})");
}

/// <summary>A takeover: the process closes the journals' open ledger at its recovered end and opens its successor.</summary>
internal sealed record JournalTakeover
{
    public static JournalTakeover Instance { get; } = new();

    public override string ToString() => "Takeover";
}

/// <summary>One run of the owner's expiry scan, with a tombstone retention of zero (journals.md §8.6).</summary>
internal sealed record JournalScan
{
    public static JournalScan Instance { get; } = new();

    public override string ToString() => "ExpiryScan";
}

/// <summary>
/// The answer to a write or a read: the operation as it ran, its expected version resolved, the answer as
/// <see cref="JournalModel"/> takes it, and the replace request it carried (journals.md §2.4).
/// </summary>
internal sealed record JournalAnswer(JournalInput Input, JournalOutput Output, bool ReplaceRequested = false)
{
    public override string ToString() =>
        JournalModel.Instance.DescribeOperation(Input, Output) + (ReplaceRequested ? ", replace requested" : string.Empty);
}

/// <summary>An expiry scan's answer: each <c>Expired</c> it proposed, in order, with its outcome.</summary>
internal sealed record JournalScanAnswer(ImmutableArray<JournalAnswer> Proposals)
{
    public override string ToString() => Proposals.IsEmpty ? "proposed nothing" : string.Join("; ", Proposals);
}

/// <summary>A takeover's answer: the process serves the successor.</summary>
internal sealed record JournalTakenOver
{
    public static JournalTakenOver Instance { get; } = new();

    public override string ToString() => "TakenOver";
}

/// <summary>The archive store's limits as the spec judges them: those of <c>InMemoryArchiveStore</c>.</summary>
/// <param name="MaxAppends">The most appends an append run may bring a generation to.</param>
/// <param name="ReplaceRequestAppends">The appends of a generation at which the store asks for a <c>Replace</c>.</param>
internal sealed record JournalStoreSpecOptions(int MaxAppends, int ReplaceRequestAppends);

/// <summary>
/// The executable spec of the Journals contract (journals.md §2, JS-I1 to JS-I4, JS-I7), as one process's
/// <c>JournalStore</c> answers it, whose state is <see cref="JournalModelState"/> per journal, so the oracle which
/// judges observed histories (<see cref="JournalModel"/>, verification.md §3.4) judges generated sequences too.
/// </summary>
/// <remarks>
/// <para>
/// Every write and read answer goes through <see cref="JournalModel.Step"/>: admission by expected version, the fold a read
/// returns, and no effect for <c>Rejected</c>, <c>ReplaceRequired</c>, <c>Moved</c>, and <c>Fenced</c>. On top of it the
/// spec holds what the model leaves open and this composition decides. A process serving the journals answers a write
/// <c>Accepted</c>, <c>Rejected</c>, or <c>ReplaceRequired</c>, and one serving none answers every call <c>Moved</c>. A
/// write during a takeover may also be <c>Fenced</c>, or <c>Moved</c> while the registry does not yet serve the
/// successor's writer, and a write during a crash <c>Ambiguous</c>, an <c>Expect.OneOf</c> beside its answered outcomes
/// whose entry is a pending step function: it lands once, at any later point where its expected version still names the
/// journal's state, or never. The store's limits refuse an
/// <c>Append</c> exactly when its generation, the appends since the journal's opener, holds
/// <see cref="JournalStoreSpecOptions.MaxAppends"/>: admission admits one only when both candidate writes do, the key's
/// write in the open segment and a write which a new segment starts at the admitted token (journals.md §8.1), and the
/// second judges the generation alone. An <c>Accepted</c> answer and a read carry the replace request of journals.md
/// §2.4 and §8.7.
/// </para>
/// <para>
/// The state profile is strict about names: no ledger of this composition is dropped, so no load rebases a key, and an
/// answer names a state by one of its names, or by a fresh version only once an ambiguous entry or an <c>Expired</c>
/// left the state's names unknown; and a <c>Rejected</c> write applies to no state (JS-I1). <see cref="JournalModel"/>
/// alone takes a fresh version as a rebase, which an answer may name a state by once its rows dropped.
/// </para>
/// </remarks>
internal static class JournalStoreSpec
{
    /// <summary>The name of a write in a steady process.</summary>
    internal const string Write = "Write";

    /// <summary>The name of a write during a takeover.</summary>
    internal const string FencedWrite = "FencedWrite";

    /// <summary>The name of a write during a crash.</summary>
    internal const string CrashingWrite = "CrashingWrite";

    /// <summary>The name of a read.</summary>
    internal const string Read = "Read";

    /// <summary>The name of a takeover.</summary>
    internal const string Takeover = "Takeover";

    /// <summary>The name of an expiry scan.</summary>
    internal const string ExpiryScan = "ExpiryScan";

    /// <summary>Gets the journals' keys.</summary>
    internal static ImmutableArray<string> Keys { get; } = ["a", "b"];

    /// <summary>
    /// Returns a write's payload: an append's, <paramref name="value"/> one to three times; a replace's snapshot,
    /// <paramref name="value"/> zero to three times, so a snapshot may be empty; nothing for a delete.
    /// </summary>
    internal static byte[] Payload(JournalWriteKind kind, byte value) => kind switch
    {
        JournalWriteKind.Append => [.. Enumerable.Repeat(value, 1 + value % 3)],
        JournalWriteKind.Replace => [.. Enumerable.Repeat(value, value % 4)],
        JournalWriteKind.Delete => [],
        _ => throw new ArgumentOutOfRangeException(nameof(kind), kind, "Undefined write kind."),
    };

    /// <summary>Returns the name of the spec operation <paramref name="request"/> belongs to.</summary>
    internal static string OperationOf(object request) => request switch
    {
        JournalWrite { Disruption: JournalDisruption.None } => Write,
        JournalWrite { Disruption: JournalDisruption.Takeover } => FencedWrite,
        JournalWrite { Disruption: JournalDisruption.Crash } => CrashingWrite,
        JournalRead => Read,
        JournalTakeover => Takeover,
        JournalScan => ExpiryScan,
        _ => throw new ArgumentOutOfRangeException(nameof(request), request, "Not a request of the Journals spec."),
    };

    /// <summary>
    /// Returns whether a caller may not issue <paramref name="second"/> concurrently with <paramref name="first"/>: the
    /// environment's steps (a takeover, and a write during one or during a crash) run alone, and the composition runs one
    /// expiry scan at a time (journals.md §8.6).
    /// </summary>
    internal static bool Conflicts(object first, object second) =>
        IsEnvironment(first) || IsEnvironment(second) || first is JournalScan && second is JournalScan;

    /// <summary>Creates the spec, which judges the store's limits as <paramref name="options"/> set them.</summary>
    internal static Spec<JournalStoreState> Create(JournalStoreSpecOptions options)
    {
        var spec = new Spec<JournalStoreState>();
        spec.Operation<JournalWrite, JournalAnswer>(Write, (request, state) => WriteOutcome(request, state, options));
        spec.Operation<JournalWrite, JournalAnswer>(FencedWrite, (request, state) => WriteOutcome(request, state, options));
        spec.Operation<JournalWrite, JournalAnswer>(CrashingWrite, (request, state) => WriteOutcome(request, state, options));
        spec.Operation<JournalRead, JournalAnswer>(Read, (request, state) => ReadOutcome(request, state, options));
        spec.Operation<JournalTakeover, JournalTakenOver>(
            Takeover,
            static (_, _) => Expect.That<JournalTakenOver>(static _ => true, "A takeover answers once the process serves the successor.")
                .ThenState<JournalStoreState>(TakeOver));
        spec.Operation<JournalScan, JournalScanAnswer>(ExpiryScan, (_, state) => ScanOutcome(state));
        return spec;
    }

    private static bool IsEnvironment(object request) =>
        request is JournalTakeover or JournalWrite { Disruption: not JournalDisruption.None };

    /// <summary>The process serves the successor of the journals' open ledger.</summary>
    private static void TakeOver(JournalStoreState state) => state.Served = true;

    private static ExpectedOutcomes WriteOutcome(JournalWrite request, JournalStoreState state, JournalStoreSpecOptions options)
    {
        var disruption = request.Disruption;
        if (!state.Served)
        {
            return Expect.That<JournalAnswer>(answer => IsWrite(request, answer) && answer.Output.Outcome == JournalOutcome.Moved
                    ? ValidationResult.Valid()
                    : ValidationResult.Invalid("journals.md §2.2: a process which serves no open ledger over the journals answers every write Moved, without effect (JS-I4)."))
                .ThenState<JournalStoreState>(next =>
                {
                    if (disruption == JournalDisruption.Takeover)
                    {
                        TakeOver(next);
                    }
                });
        }

        var answered = Expect.That<JournalAnswer>(answer => Answered(request, state, answer, options))
            .ThenState<JournalStoreState>(
                (answer, next) =>
                {
                    ApplyAnswer(next, request.Key, answer);
                    Disrupt(next, disruption);
                },
                () => new JournalAnswer(JournalInput.Read(Keys[request.Key]), JournalOutput.Moved));
        return disruption switch
        {
            JournalDisruption.None => answered,
            JournalDisruption.Takeover => Expect.OneOf(
                answered,
                Expect.That<JournalAnswer>(answer => IsWrite(request, answer) && answer.Output.Outcome is JournalOutcome.Fenced or JournalOutcome.Moved
                        ? ValidationResult.Valid()
                        : ValidationResult.Invalid("JS-I4: a write the takeover fences is Fenced, or Moved while the process does not yet serve the successor's writer, without effect."))
                    .ThenState<JournalStoreState>(TakeOver)),
            JournalDisruption.Crash => Expect.OneOf(
                answered,
                Expect.That<JournalAnswer>(answer => IsWrite(request, answer) && answer.Output.Outcome == JournalOutcome.Ambiguous
                        ? ValidationResult.Valid()
                        : ValidationResult.Invalid("journals.md §2.2: a write whose batch the crash left undecided is Ambiguous, and may still land, at most once."))
                    .ThenState<JournalStoreState>(static next => next.Served = false)
                    .Triggers(answer => new Landing(request.Key, answer?.Input))),
            _ => throw new ArgumentOutOfRangeException(nameof(request), disruption, "Undefined disruption."),
        };
    }

    /// <summary>Takes the environment's step after a write answered: a takeover serves the successor, and a crash serves nothing.</summary>
    private static void Disrupt(JournalStoreState state, JournalDisruption disruption)
    {
        switch (disruption)
        {
            case JournalDisruption.None:
                break;
            case JournalDisruption.Takeover:
                TakeOver(state);
                break;
            case JournalDisruption.Crash:
                state.Served = false;
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(disruption), disruption, "Undefined disruption.");
        }
    }

    /// <summary>Returns whether <paramref name="answer"/> is of <paramref name="request"/>: its key, kind, and payload.</summary>
    private static bool IsWrite(JournalWrite request, JournalAnswer answer) =>
        answer.Input.Kind == request.Operation
        && answer.Input.Key == Keys[request.Key]
        && answer.Input.Expected is not null
        && answer.Input.Payload.Span.SequenceEqual(request.Payload);

    /// <summary>
    /// Judges a write a serving process answered: <see cref="JournalModel"/>'s step, names as the strict profile allows
    /// them, the store's limits, and the replace request.
    /// </summary>
    private static ValidationResult Answered(JournalWrite request, JournalStoreState state, JournalAnswer answer, JournalStoreSpecOptions options)
    {
        if (!IsWrite(request, answer))
        {
            return ValidationResult.Invalid(Invariant($"The answer is not of the write {request}."));
        }

        var journal = state.Journals[request.Key];
        var expected = answer.Input.Expected!;
        var output = answer.Output;
        if (output.Outcome is not (JournalOutcome.Accepted or JournalOutcome.Rejected or JournalOutcome.ReplaceRequired))
        {
            return ValidationResult.Invalid(Invariant($"journals.md §2.2: a process serving the journal, which no takeover or crash disturbs, answers a write Accepted, Rejected, or ReplaceRequired; the journal is {journal}."));
        }

        if (!JournalModel.Instance.Step(journal, answer.Input, output, out var next))
        {
            return ValidationResult.Invalid(Invariant($"JS-I1, JS-I4 (JournalModel): the journal at {journal} does not answer {answer}: an entry is accepted only at a version naming its state, which it moves to a version that never named one, and an answer without effect reports a name of the state."));
        }

        var applies = journal.Names.Contains(expected);
        if (output.Outcome == JournalOutcome.Rejected && applies)
        {
            return ValidationResult.Invalid(Invariant($"JS-I1: an entry whose expected version {expected} names the journal's state {journal} applies to it, and is not Rejected."));
        }

        if (output.Outcome == JournalOutcome.Rejected && !Names(journal, output.Version!))
        {
            return ValidationResult.Invalid(Invariant($"journals.md §2.2: a rejection's CurrentVersion {output.Version} names the journal's state {journal}, and no load rebases a key whose ledgers no drop removed."));
        }

        if (request.Kind == JournalWriteKind.Append && output.Outcome != JournalOutcome.Rejected)
        {
            var refused = journal.Appends >= options.MaxAppends;
            if (refused != (output.Outcome == JournalOutcome.ReplaceRequired))
            {
                return ValidationResult.Invalid(Invariant($"journals.md §2.2, §8.1: the store's limits refuse an Append exactly when its generation, the appends since the journal's opener, holds {options.MaxAppends}; the journal at {journal} holds {journal.Appends}."));
            }
        }

        if (output.Outcome == JournalOutcome.Accepted)
        {
            var requested = next.Content.Length > 2L * next.BaseLength || next.Appends >= options.ReplaceRequestAppends;
            if (answer.ReplaceRequested != requested)
            {
                return ValidationResult.Invalid(Invariant($"journals.md §2.4, §8.7: an Accepted answer carries a replace request when its content ({next.Content.Length} bytes) passes twice its base's {next.BaseLength} bytes, or when the store asks for one at its generation of {next.Appends} appends (threshold {options.ReplaceRequestAppends})."));
            }
        }

        if (output.Outcome != JournalOutcome.Accepted && answer.ReplaceRequested)
        {
            return ValidationResult.Invalid("journals.md §2.4: only an Accepted answer carries a replace request.");
        }

        return ValidationResult.Valid();
    }

    /// <summary>Applies the effect of a write's answer, which <see cref="Answered"/> allowed.</summary>
    private static void ApplyAnswer(JournalStoreState state, int key, JournalAnswer answer)
    {
        if (!JournalModel.Instance.Step(state.Journals[key], answer.Input, answer.Output, out var next))
        {
            throw new InvalidOperationException(Invariant($"The spec applies only an answer it allowed, not {answer}."));
        }

        state.SetJournal(key, next);
    }

    /// <summary>
    /// Returns whether an answer may name <paramref name="journal"/>'s state by <paramref name="version"/>: one of its
    /// names, or, while its names are unknown, a version which never named a state.
    /// </summary>
    private static bool Names(JournalModelState journal, string version) =>
        journal.Names.Contains(version) || journal.Names.IsEmpty && !journal.Held.Contains(version);

    private static ExpectedOutcomes ReadOutcome(JournalRead request, JournalStoreState state, JournalStoreSpecOptions options)
    {
        var key = Keys[request.Key];
        if (!state.Served)
        {
            return Expect.That<JournalAnswer>(answer => answer.Input.Key == key && answer.Input.Kind == JournalOperationKind.Read && answer.Output.Outcome == JournalOutcome.Moved
                    ? ValidationResult.Valid()
                    : ValidationResult.Invalid("journals.md §2.3: a process which serves no open ledger over the journals answers every read Moved."))
                .SameState();
        }

        var journal = state.Journals[request.Key];
        return Expect.That<JournalAnswer>(answer =>
            {
                if (answer.Input.Key != key || answer.Input.Kind != JournalOperationKind.Read || answer.Output.Outcome != JournalOutcome.Accepted)
                {
                    return ValidationResult.Invalid(Invariant($"journals.md §2.3: a process serving the journal answers its read with the journal's state, {journal}."));
                }

                if (!JournalModel.Instance.Step(journal, answer.Input, answer.Output, out _) || !Names(journal, answer.Output.Version!))
                {
                    return ValidationResult.Invalid(Invariant($"JS-I3: a read returns the fold of every acknowledged entry and of decided entries only, the journal's state {journal}, by one of its names."));
                }

                var requested = answer.Output.Content.Length > 2L * journal.BaseLength || journal.Appends >= options.ReplaceRequestAppends;
                return answer.ReplaceRequested == requested
                    ? ValidationResult.Valid()
                    : ValidationResult.Invalid(Invariant($"journals.md §2.4, §8.7: a read requests a Replace when its content passes twice its base's {journal.BaseLength} bytes, or when the store asks for one at its generation of {journal.Appends} appends."));
            })
            .ThenState<JournalStoreState>(
                (answer, next) =>
                {
                    _ = JournalModel.Instance.Step(next.Journals[request.Key], answer.Input, answer.Output, out var named);
                    next.SetJournal(request.Key, named);
                },
                () => new JournalAnswer(JournalInput.Read(key), JournalOutput.Moved));
    }

    /// <summary>
    /// journals.md §8.6, JS-I1, JS-I7: each <c>Expired</c> the scan proposes is judged as <see cref="JournalModel"/> judges
    /// one, in the order it proposed them; a process which serves nothing proposes nothing.
    /// </summary>
    private static ExpectedOutcome ScanOutcome(JournalStoreState state) =>
        Expect.That<JournalScanAnswer>(answer =>
            {
                if (!state.Served)
                {
                    return answer.Proposals.IsEmpty
                        ? ValidationResult.Valid()
                        : ValidationResult.Invalid("journals.md §8.6: a process which serves no admission has no warm state to scan.");
                }

                var journals = state.Journals.ToList();
                foreach (var proposal in answer.Proposals)
                {
                    var key = Keys.IndexOf(proposal.Input.Key);
                    if (key < 0 || proposal.Input.Kind != JournalOperationKind.Expire || proposal.Output.Outcome is not (JournalOutcome.Accepted or JournalOutcome.Rejected))
                    {
                        return ValidationResult.Invalid(Invariant($"journals.md §8.6: a scan proposes the Expired of a journal, which a serving process answers Accepted or Rejected, not {proposal}."));
                    }

                    if (!JournalModel.Instance.Step(journals[key], proposal.Input, proposal.Output, out var next)
                        || proposal.Output.Outcome == JournalOutcome.Rejected && !Names(journals[key], proposal.Output.Version!)
                        || proposal.ReplaceRequested)
                    {
                        return ValidationResult.Invalid(Invariant($"JS-I1, JS-I7: an Expired is accepted only at a version naming its journal's deleted state, {journals[key]}, and a rejection reports a name of the state."));
                    }

                    journals[key] = next;
                }

                return ValidationResult.Valid();
            })
            .ThenState<JournalStoreState>(
                (answer, next) =>
                {
                    foreach (var proposal in answer.Proposals)
                    {
                        var key = Keys.IndexOf(proposal.Input.Key);
                        _ = JournalModel.Instance.Step(next.Journals[key], proposal.Input, proposal.Output, out var stepped);
                        next.SetJournal(key, stepped);
                    }
                },
                static () => new JournalScanAnswer([]));

    private static string Invariant(FormattableString value) => FormattableString.Invariant(value);

    /// <summary>
    /// An entry whose write answered <c>Ambiguous</c>, which may land once, at any later point where its expected version
    /// still names its journal's state, or never (journals.md §2.2). Accordant's generation, which runs no system, knows no
    /// entry, and none lands.
    /// </summary>
    private sealed class Landing(int key, JournalInput? input) : BaseStepFunction
    {
        public override string StepFunctionId => input is { } entry
            ? "landing of " + JournalModel.Instance.DescribeOperation(entry, JournalOutput.Ambiguous)
            : "landing of no entry";

        protected override IList<StepResult> ApplyInternal(IState state)
        {
            var next = (JournalStoreState)((JournalStoreState)state).Clone();
            var journal = next.Journals[key];
            if (input is { } entry && journal.Names.Contains(entry.Expected!) && JournalModel.Instance.Step(journal, entry, JournalOutput.Ambiguous, out var landed))
            {
                next.SetJournal(key, landed);
            }

            return [new StepResult { State = next }];
        }
    }
}
